css:
.calibra-sim-container {
    padding: 28px 32px;
    background: #f4f5f7;
    min-height: 100vh;
    font-family: -apple-system, 'Segoe UI', 'Inter', Helvetica, Arial, sans-serif;
    color: #1a2744;
    line-height: 1.55;
}
.calibra-sim-header {
    background: linear-gradient(135deg, #1a2744 0%, #2c3e6b 100%);
    color: #ffffff;
    padding: 32px 36px 28px;
    border-radius: 4px;
    margin-bottom: 24px;
    position: relative;
    overflow: hidden;
}
.calibra-sim-header::after {
    content: '';
    position: absolute;
    top: 0; right: 0;
    width: 200px; height: 100%;
    background: linear-gradient(135deg, rgba(255,255,255,0) 0%, rgba(255,255,255,0.04) 100%);
}
.calibra-sim-header-badge {
    font-size: 0.7rem;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    color: rgba(255,255,255,0.6);
    margin-bottom: 8px;
    font-weight: 600;
}
.calibra-sim-header h1 {
    margin: 0 0 6px;
    font-size: 1.65rem;
    font-weight: 700;
    letter-spacing: -0.01em;
}
.calibra-sim-subtitle {
    margin: 0;
    font-size: 0.88rem;
    color: rgba(255,255,255,0.7);
    font-weight: 400;
}
.calibra-sim-period-counter {
    text-align: center;
    font-size: 0.85rem;
    color: #5a6578;
    margin-bottom: 20px;
    font-weight: 500;
    letter-spacing: 0.04em;
    text-transform: uppercase;
}
.calibra-sim-period-counter span {
    margin: 0 3px;
}
.calibra-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 14px;
    margin-bottom: 24px;
}
.calibra-sim-kpi-card {
    background: #ffffff;
    border: 1px solid #e1e4e8;
    border-radius: 4px;
    padding: 18px 14px 16px;
    text-align: center;
    transition: box-shadow 0.2s ease, border-color 0.2s ease;
}
.calibra-sim-kpi-card:hover {
    box-shadow: 0 3px 12px rgba(26,39,68,0.08);
    border-color: #c8cdd5;
}
.calibra-sim-kpi-accent {
    border-left: 3px solid #1a2744;
}
.calibra-sim-kpi-icon {
    font-size: 1.3rem;
    margin-bottom: 6px;
}
.calibra-sim-kpi-label {
    font-size: 0.68rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: #66717f;
    margin-bottom: 6px;
    font-weight: 600;
}
.calibra-sim-kpi-value {
    font-size: 1.6rem;
    font-weight: 700;
    color: #1a2744;
}
.calibra-sim-briefing {
    background: #ffffff;
    border: 1px solid #e1e4e8;
    border-radius: 4px;
    padding: 24px 28px;
    margin-bottom: 24px;
    position: relative;
}
.calibra-sim-briefing-bar {
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
    background: linear-gradient(90deg, #1a2744, #3b5998);
    border-radius: 4px 4px 0 0;
}
.calibra-sim-briefing-header {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: #66717f;
    font-weight: 700;
    margin-bottom: 12px;
}
.calibra-sim-briefing-body {
    font-size: 0.92rem;
    color: #374151;
    line-height: 1.7;
}
.calibra-sim-controls {
    background: #ffffff;
    border: 1px solid #e1e4e8;
    border-radius: 4px;
    padding: 24px 28px;
    margin-bottom: 24px;
}
.calibra-sim-controls h3 {
    font-size: 0.95rem;
    font-weight: 700;
    color: #1a2744;
    margin: 0 0 18px;
    padding-bottom: 10px;
    border-bottom: 1px solid #eef0f3;
}
.calibra-sim-field {
    margin-bottom: 16px;
}
.calibra-sim-field label {
    display: block;
    font-size: 0.82rem;
    font-weight: 600;
    color: #374151;
    margin-bottom: 5px;
}
.calibra-sim-field input[type="number"],
.calibra-sim-field select {
    width: 100%;
    max-width: 340px;
    padding: 9px 12px;
    border: 1px solid #d1d5db;
    border-radius: 3px;
    font-size: 0.9rem;
    color: #1a2744;
    background: #fafbfc;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.calibra-sim-field input[type="number"]:focus,
.calibra-sim-field select:focus {
    outline: none;
    border-color: #3b5998;
    box-shadow: 0 0 0 3px rgba(59,89,152,0.12);
}
.calibra-sim-field small {
    display: block;
    font-size: 0.75rem;
    color: #646d79;
    margin-top: 4px;
}
.calibra-sim-btn-row {
    margin-top: 20px;
    display: flex;
    align-items: center;
    gap: 12px;
}
.calibra-sim-submit-btn {
    background: #1a2744;
    border-color: #1a2744;
    color: #ffffff;
    padding: 10px 28px;
    font-weight: 600;
    font-size: 0.88rem;
    border-radius: 3px;
    transition: background 0.2s ease;
}
.calibra-sim-submit-btn:hover {
    background: #2c3e6b;
    border-color: #2c3e6b;
}
.calibra-sim-undo-btn {
    font-size: 0.8rem;
    color: #66717f;
    border-color: #d1d5db;
}
.calibra-sim-results {
    background: #ffffff;
    border: 1px solid #e1e4e8;
    border-left: 3px solid #2d8a4e;
    border-radius: 4px;
    padding: 22px 28px;
    margin-bottom: 24px;
}
.calibra-sim-results-header {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: #297e47;
    font-weight: 700;
    margin-bottom: 10px;
}
.calibra-sim-results-body {
    font-size: 0.88rem;
    color: #374151;
    line-height: 1.7;
}
.calibra-sim-history {
    margin-bottom: 24px;
}
.calibra-sim-container .table {
    background: #ffffff;
    border: 1px solid #e1e4e8;
    border-radius: 4px;
    font-size: 0.82rem;
}
.calibra-sim-container .table thead th {
    background: #f4f5f7;
    color: #1a2744;
    font-weight: 700;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    border-bottom: 2px solid #e1e4e8;
    padding: 10px 12px;
}
.calibra-sim-container .table td {
    padding: 9px 12px;
    vertical-align: middle;
    color: #374151;
}
.calibra-sim-chart-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
    margin-bottom: 24px;
}
.calibra-sim-chart-box {
    background: #ffffff;
    border: 1px solid #e1e4e8;
    border-radius: 4px;
    padding: 20px;
    min-height: 280px;
    position: relative;
}
@media (max-width: 992px) {
    .calibra-sim-kpi-grid {
        grid-template-columns: repeat(3, 1fr);
    }
    .calibra-sim-chart-row {
        grid-template-columns: 1fr;
    }
}
@media (max-width: 768px) {
    .calibra-sim-container {
        padding: 16px;
    }
    .calibra-sim-kpi-grid {
        grid-template-columns: repeat(2, 1fr);
    }
    .calibra-sim-header {
        padding: 22px 20px;
    }
    .calibra-sim-header h1 {
        font-size: 1.3rem;
    }
    .calibra-sim-field input[type="number"],
    .calibra-sim-field select {
        max-width: 100%;
    }
}
/* EQIL 2026-11-12: contrast to AA, visible focus, reduced motion, completion debrief */
.calibra-sim-container button:focus-visible, .calibra-sim-container input:focus-visible, .calibra-sim-container select:focus-visible { outline: 3px solid #1a2744; outline-offset: 2px; }
@media (prefers-reduced-motion: reduce) { .calibra-sim-container * { transition: none !important; animation: none !important; } }
.calibra-sim-cm { text-align: left; }
.calibra-sim-cm-kpis { list-style: none; padding: 0; display: flex; flex-wrap: wrap; gap: 6px 16px; }
.calibra-sim-cm h4 { font-size: 1rem; margin-top: 12px; }

