        getPerformanceSummary(history) {
            if (!history.length) return {};
            var lastEntry = history[history.length - 1];
            var r = lastEntry.results || {};
            var totalSpent = 1500 - (r.budgetRemaining || 0);
            var retention = r.retentionRate || 85;
            var fairness = r.fairnessScore || 35;
            var satisfaction = r.satisfactionScore || 45;
            var recovered = r.talentRecovered || 0;
            var composite = this._composite(retention, fairness, satisfaction, recovered);
            var performance = this._band(composite);

            var t = function(k) { return window.mySimulation.t(k); };
            var dec = {};
            for (var hi = 0; hi < history.length; hi++) {
                var rec = history[hi] || {};
                var pk = parseInt(rec.period !== undefined ? rec.period : rec.currentPeriod, 10);
                if (pk >= 1 && pk <= 4) dec[pk] = rec.decisions || {};
            }
            var made = [];
            var d1 = dec[1] || {}, d2 = dec[2] || {}, d3 = dec[3] || {}, d4 = dec[4] || {};
            if (parseInt(d1.focusArea, 10) === 1) made.push('dm_m1');
            else if (parseInt(d1.focusArea, 10) === 2) made.push('dm_eval');
            if (dec[2] && (+d2.salaryBudget > 300) && (+d2.calibrationInvest < 40)) made.push('dm_m2');
            if (dec[3] && (+d3.recoveryBudget > 200)) made.push('dm_m3');
            if (dec[3] && (+d3.trainingBudget < 60)) made.push('dm_m4');
            if (dec[4] && parseInt(d4.implSpeed, 10) === 1) made.push('dm_m5');
            var turningKey = made.length ? made[0] : 'cm_tp_none';
            var insightKeys = made.slice(1);
            insightKeys.push(retention >= 92 ? 'ins_ret_hi' : 'ins_ret_lo');
            insightKeys.push(fairness >= 70 ? 'ins_fair_hi' : 'ins_fair_lo');
            insightKeys.push(recovered >= 2 ? 'ins_rec_hi' : 'ins_rec_lo');
            if ((r.budgetRemaining || 0) < 100) insightKeys.push('ins_fund_low');
            insightKeys = insightKeys.slice(0, 5);
            var insights = insightKeys.map(t);

            return {
                totalSpent: totalSpent,
                overallScore: composite,
                score: composite,
                retention: retention,
                fairness: fairness,
                satisfaction: satisfaction,
                talentRecovered: recovered,
                composite: composite,
                performance: performance,
                performanceKey: 'band_' + performance.toLowerCase().split(' ')[0],
                performanceLabel: t('band_' + performance.toLowerCase().split(' ')[0]),
                budgetRemaining: (r.budgetRemaining || 0),
                mistakes: made,
                turningPoint: t(turningKey),
                turningPointKey: turningKey,
                insights: insights,
                insightKeys: insightKeys,
                questions: [t('cm_q1'), t('cm_q2'), t('cm_q3')]
            };
        }

        formatCompletionMessage(summary) {
            var t = function(k) { return window.mySimulation.t(k); };
            if (!summary || summary.score === undefined) return '<div class="calibra-sim-cm"><p>' + t('cm_title') + '</p></div>';
            var esc = function(x) { return String(x === undefined || x === null ? '' : x).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
            var h = '<div class="calibra-sim-cm" role="region" aria-label="' + esc(t('cm_title')) + '">';
            h += '<h3 class="calibra-sim-cm-title">' + esc(t('cm_title')) + '</h3>';
            h += '<p class="calibra-sim-cm-score"><strong>' + esc(summary.score) + ' / 100</strong> · ' + esc(summary.performanceLabel) + '</p>';
            h += '<ul class="calibra-sim-cm-kpis">';
            h += '<li>' + esc(t('retention_label')) + ': ' + esc(summary.retention) + '%</li>';
            h += '<li>' + esc(t('fairness_label')) + ': ' + esc(summary.fairness) + ' / 100</li>';
            h += '<li>' + esc(t('satisfaction_label')) + ': ' + esc(summary.satisfaction) + ' / 100</li>';
            h += '<li>' + esc(t('recovered_label')) + ': ' + esc(summary.talentRecovered) + ' / 5</li>';
            h += '<li>' + esc(t('budget_label')) + ': $' + esc(Math.round(summary.budgetRemaining || 0)) + 'K</li>';
            h += '</ul>';
            h += '<h4>' + esc(t('cm_tp')) + '</h4><p>' + esc(summary.turningPoint) + '</p>';
            h += '<h4>' + esc(t('cm_ins')) + '</h4><ul>';
            (summary.insights || []).forEach(function(x) { h += '<li>' + esc(x) + '</li>'; });
            h += '</ul><h4>' + esc(t('cm_q')) + '</h4><ol>';
            (summary.questions || []).forEach(function(x) { h += '<li>' + esc(x) + '</li>'; });
            h += '</ol></div>';
            return h;
        }

